styl:
.b-iq-hero-31 u + .body .gmail-blend-screen {  background: #000;
  mix-blend-mode: screen;  }
.b-iq-hero-31 u + .body .gmail-blend-diff {  background: #000;
  mix-blend-mode: difference;  }
.bgr-image.b-iq-hero-31 {  background: url("https://fsms.quadcode.com/storage/public/d8/6m/k0i61bdc700vi7v0/2-2-4-bg.png") center top no-repeat;
  background-size: cover;
  background-color: #000;  }
.b-iq-hero-31 .w280 {  width: 100%;
  max-width: 280px;  }
@media screen and (max-width: 600px) {
  .b-iq-hero-31 .w280 {  max-width: 100% !important;  }
}
.brad-full.b-iq-hero-31 {  border-radius: 32px !important;  }
.b-iq-hero-31 .butt-link {  font-size: 18px;
  line-height: 27px;
  font-weight: 700;
  text-transform: none;
  text-decoration: none;
  color: #f9f9f9;
  display: block;
  padding: 16px 0 16px;
  text-align: center;
  letter-spacing: 0px;  }
.b-iq-hero-31 .white-title {  font-family: Helvetica !important;
  font-weight: 700;
  font-size: 42px;
  line-height: 52px;
  color: #f9f9f9;
  word-break: break-word;
  padding-right: 30px;  }
@media screen and (max-width: 600px) {
  .b-iq-hero-31 .white-title {  font-size: 26px !important;
    line-height: 32px !important;  }
}
.b-iq-hero-31 .white-text {  font-family: Helvetica !important;
  font-style: normal;
  font-weight: 400;
  font-size: 18px;
  line-height: 27px;
  color: #fff;
  padding-right: 20px;  }
@media screen and (max-width: 600px) {
  .b-iq-hero-31 .white-text {  padding-right: 0 !important;  }
}
